	(1, 'Website_Title', '<p>Adriana Granobles</p>', 'sp'),
	(2, 'Website_Slogan', '<p>Clases de M&uacute;sica y Producci&oacute;n Musical, Servicio personalizado y a domicilio</p>', 'sp'),
	(3, 'Website_Logo', 'logo.png', 'sp'),
	(5, 'Website_Footer', '<article class="col-lg-12 col-md-12 col-sm-12">\r\n<ul class="sitemap-1">\r\n<li><a href="/clases/quien-es-adriana">Quien es Adriana</a></li>\r\n<li><a href="/clases/quien-es-adriana">Testimonios</a></li>\r\n<li><a href="/clases/">Clases</a></li>\r\n<li><a href="/estudio-de-grabacion/">Estudio de grabación</a></li>\r\n<li><a href="/precios/">Precios</a></li>\r\n</ul>\r\n\r\n</article>\r\n\r\n<article class="col-lg-4 col-md-4 col-sm-4">\r\n  <figure><img src="/img/foo_icon1.png" alt=""></figure>\r\n                <div class="extra-wrap">\r\n                    <p>ADRIANA GRANOBLES<br>Bogotá, Colombia</p>\r\n                </div>\r\n<img src="/images/articles/LOGO-CAMARA-DE-COMERCIO-BOGOTA.gif" alt="">\r\n            </article>\r\n            <article class="col-lg-4 col-md-4 col-sm-4">\r\n                <figure><img src="/img/foo_icon2.png" alt=""></figure>\r\n                <div class="extra-wrap">\r\n                    <p>Teléfono: (321) 240-9712<br><a href="mailto:musica@adrianagranobles.com">musica@adrianagranobles.com</a></p>\r\n                </div>\r\n            </article>\r\n            <article class="col-lg-4 col-md-4 col-sm-4">\r\n                <p><strong>Otros Websites AG:</strong></p>\r\n<p>• <a href="http://direct.me/cetonasanivelmundial" target="_blank">Cetonas Adriana Y Katia on Direct.me</a></p>\r\n	<p>• <a href="https://adrianagranobles.com/ProyectoPurpura/index.html" target="_blank">Proyecto Purpura</a></p>\r\n\r\n            </article>\r\n<br clear="all">\r\n<p> </p>\r\n<article class="col-lg-12 col-md-12 col-sm-12">\r\n	<p class="priv"><strong>Adriana Granobles</strong><br/> © Todos los derechos reservados <em id="copyright-year"></em><!-- | <a href="index-5.html">Privacy Policy</a></p>-->\r\n                <ul>\r\n                	<li><a href="https://www.facebook.com/pages/AG-Clases-de-M%C3%BAsica/122447191147156" target="_blank"><img src="/img/follow_icon1.png" alt=""></a></li>\r\n                	<!--<li><a href="#"  target="_blank"><img src="/img/follow_icon2.png" alt=""></a></li>-->\r\n                	<li><a href="https://twitter.com/Adrigranobles"  target="_blank"><img src="/img/follow_icon3.png" alt=""></a></li>\r\n                	<li><a href="https://plus.google.com/100016058227516121468/posts"  target="_blank"><img src="/img/follow_icon4.png" alt=""></a></li>\r\n<li><a href="https://www.youtube.com/user/agclasesdemusica" target="_blank"><img src="/img/follow_icon5.png" alt=""></a></li>\r\n                </ul>\r\n	</article>\r\n<p> </p>', 'sp'),
	(4, 'Website_Header', '<article class="col-lg-4">\r\n<h1 class="navbar-brand navbar-brand_"><a href="/"><img src="/images/articles/logo.png" alt=""></a></h1>\r\n</article><article class="col-lg-8"><div>\r\n<img src="/img/head_icon.png" alt="" style="height: 18px; margin-top: 5px"><a href="#">Tel: +57 1 564-1395 Bogotá</a><br/><a href="https://wa.me/573212409712" target="_blank">Cel: +57 321 240-9712 <img src="/images/articles/WhatsApp_Logo_5.png" style="padding-top:4px; margin-right:0px; margin-left: 5px; float:right;" ></a><br/><div id="google_translate_element"></div></div>\r\n\r\n\r\n\r\n	<script type="text/javascript">  \r\n        function googleTranslateElementInit() {  \r\n            new google.translate.TranslateElement( \r\n                {pageLanguage: \'sp\'},  \r\n                \'google_translate_element\' \r\n            );  \r\n        }  \r\n    </script>  \r\n      \r\n    <script type="text/javascript" src="https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit"></script>\r\n</article>\r\n', 'sp'),
