INSERT INTO `RED_Articles` (`RecordID`, `Title`, `Component`, `Alias`, `Sections`, `HomePosition`, `HomePositionOrder`, `SectionPosition`, `SectionPositionOrder`, `Categories`, `CategoryPosition`, `CategoryPositionOrder`, `SubCategories`, `SubCategoryPosition`, `SubCategoryPositionOrder`, `Layout`, `Article`, `PagePosition`, `PagePositionOrder`, `Tags`, `Active`, `HomeFeature`, `HomeFeatures`, `HomeFeatures_Order`, `SectionFeatures`, `SectionFeatures_Order`, `CategoryFeatures`, `CategoryFeatures_Order`, `SubCategoryFeatures`, `SubCategoryFeatures_Order`, `ArticleFeatures`, `StartDate`, `EventDate`, `ExpDate`, `ShortDesc`, `LongDesc`, `SliderDesc`, `Link`, `NewWindow`, `VideoSrc`, `AlbumSrc`, `BigPict`, `SmallPict`, `SmallPictAlign`, `SmallPict2`, `SmallPictAlign2`, `EditedBy`, `Language`, `Updated`) VALUES
	(966111194, 'Login', 'Form', 'login', 'administracion', 1, 5, 1, 1, '', 1, 0, '', 1, 0, 'index-2', '', 1, 0, 'login', 'Y', '', 'flex', 1, '', 0, '', 0, '', 0, '', '2012-06-01 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'Login now!', '', '', '', '', '', '', '', '', '', '', '', 'admin', 'sp', '2015-02-28 01:11:39'),
	(459269660, 'Contact', 'Form', 'contact', 'contact', 0, 0, 1, 1, '', 0, 0, '', 0, 0, 'Two-Columns', '', 1, 0, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2018-10-20 17:51:18'),
	(1636154993, 'Clases de guitarra para adultos', 'Article', 'clases-guitarra-adultos', 'clases', 0, 0, 0, 0, 'guitarra', 1, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,guitarra,adultos', 'Y', '', '', 2, 'wrapperblock', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Desarrolle las t&eacute;cnicas de ejecuci&oacute;n del instrumento a trav&eacute;s de los ejercicios, ritmos de acompa&ntilde;amiento de las canciones escogidas por el estudiante.</p>\r\n<p>Aprender las leyes fundamentales de la armon&iacute;a tradicional de la m&uacute;sica popular.</p>', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Desarrollar las t&eacute;cnicas de ejecuci&oacute;n del instrumento a trav&eacute;s de los ejercicios.</li>\r\n<li>Aprender los ritmos de acompa&ntilde;amiento de las canciones escogidas por el estudiante.</li>\r\n<li>Aprender de forma te&oacute;rica las escalas mayores y menores , y la funcionalidad de los grados que contienen.</li>\r\n<li>Aprender las leyes fundamentales de la armon&iacute;a tradicional de la m&uacute;sica popular.</li>\r\n<li>Aprender a leer y a escribir cifrados.</li>\r\n<li>Aprender las estructuras de los g&eacute;neros de las canciones que el estudiante elija.</li>\r\n<li>Desarrollar el o&iacute;do arm&oacute;nico para que el estudiante contin&uacute;e el montaje de otras canciones por su cuenta, una vez finalizado el curso.</li>\r\n<li>Grabar 10 canciones escogidas por el alumno en audio y video*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Tener instrumento para practicar.</li>\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-guitarra-adultos.jpg', '', '', 'Left', 'Admin', 'sp', '2021-05-25 00:01:01'),
	(1618140308, 'La Presidenta', 'Other', 'la-presidenta', 'servicios', 0, 0, 0, 0, '', 0, 0, '', 0, 0, 'Full-Width', '', 2, 1, 'la,presidenta', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<img src="https://adrianagranobles.com/images/articles/Screenshot_libro-katia.jpg"><form action="https://www.paypal.com/cgi-bin/webscr" method="post"><input id="submit" class="btn-default btn2" alt="Make payments with PayPal - it\'s fast, free and secure!" name="submit" type="submit" value="Comprar Ahora" /> <input name="cmd" type="hidden" value="_s-xclick" /> <input name="hosted_button_id" type="hidden" value="V5GSMR9APWAFU" /> <img src="https://www.paypalobjects.com/en_US/i/scr/pixel.gif" alt="" width="1" height="1" border="0" /></form>', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2021-05-25 00:29:53'),
	(1462567921, 'our lessons', 'Other', 'our-lessons', 'clases', 0, 0, 0, 3, '', 0, 0, '', 0, 0, 'index-2', '', 1, 0, 'our,lessons', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<h2 class="marg">Clases</h2>', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2020-09-14 22:14:55'),
	(373905986, 'Bienvenido', 'Other', 'bienvenido', 'home', 1, 1, 0, 0, '', 0, 0, '', 0, 0, 'Full-Width', '', 1, 0, 'bienvenido', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<br/><br/><h2>Bienvenido</h2>\r\n                    <div class="thumb-pad10">\r\n                        <div class="thumbnail">\r\n                            <figure><img src="https://adrianagranobles.com/images/articles/adriana-granobles-IMG_6792.JPG" width="150px" alt=""></figure>\r\n                            <div class="caption">\r\n                                <p class="title">Adriana Granobles</p>\r\n                                <p class="descrip">Compositora y Productora Musical</p>\r\n                                <!--<h3>Mes cuml dia sed inenias ingerto lot aliiqtes dolore ipsum.</h3>-->\r\n                                <p>Aquí encontrarás el camino para desarrollar tu talento musical en diferentes áreas y cumplir tu sueño de ser músico, cantante o productor musical, ya sea como aficionado o profesional. Te invito a gozar del aprendizaje de la música y sus mútiples beneficios a nivel personal y social.</p>\r\n<a href="/clases/quien-es-adriana" class="btn-default btn2">leer más</a>\r\n                            </div>\r\n                        </div>\r\n                    </div>', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2021-12-17 03:22:29'),
	(1567378737, 'Nuevos Alumnos', 'Other', 'nuevos-alumnos', 'home', 0, 1, 0, 0, '', 0, 0, '', 0, 0, 'Full-Width', '', 1, 0, 'nuevos,alumnos', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<h2>Nuevos alumnos</h2>\r\n                    <div class="row">\r\n                        <article class="col-lg-6 col-md-12 col-sm-12">\r\n                            <div class="thumb-pad3">\r\n                                <div class="thumbnail">\r\n                                    <div class="badge">\r\n                                        10\r\n                                        <span>dec</span>\r\n                                    </div>\r\n                                    <div class="caption">  \r\n                                        <h3>Mes cuml dia sed inenias cet</h3>\r\n                                        <p>Mes cuml dia sed in lacus ut eniascet ingerto aliiqt es site amet eismod ictor ut ligulate ameti dapibus.</p>\r\n                                        <a href="#" class="btn-default btn2">more</a>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </article>\r\n                        <article class="col-lg-6 col-md-12 col-sm-12">\r\n                            <div class="thumb-pad3">\r\n                                <div class="thumbnail">\r\n                                    <div class="badge">\r\n                                        12\r\n                                        <span>dec</span>\r\n                                    </div>\r\n                                    <div class="caption">  \r\n                                        <h3>Mes cuml dia sed inenias cet</h3>\r\n                                        <p>Mes cuml dia sed in lacus ut eniascet ingerto aliiqt es site amet eismod ictor ut ligulate ameti dapibus.</p>\r\n                           