	(1926717340, 'Producci&oacute;n Musical', 'Article', 'produccion-musical', 'estudio-de-grabacion', 0, 0, 1, 3, '', 0, 0, '', 0, 0, 'index-3', '', 1, 0, 'produccion,musical', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '<ul class="list1">\r\n<li>Re-estructuraci&oacute;n de canciones</li>\r\n<li>Re-armonizaci&oacute;n</li>\r\n<li>Adaptaci&oacute;n a diferentes g&eacute;neros musicales</li>\r\n<li>Arreglos</li>\r\n<li>Secuenciaci&oacute;n con instrumentos virtuales</li>\r\n<li>Grabaci&oacute;n con instrumentos reales y m&uacute;sicos de sesi&oacute;n.</li>\r\n<li>Mezcla y masterizaci&oacute;n.</li>\r\n</ul>', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2021-03-25 20:41:48'),
