	(1770579353, 'Clase de Guitarra', 'Gallery', 'clase-de-guitarra', 'clases', 2, 1, 0, 0, 'guitarra', 0, 0, '', 0, 0, '', 'clases-guitarra-adultos', 2, 2, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2015-02-23 19:45:22'),
	(894502382, 'Clases de canto para adultos', 'Article', 'clases-canto-adultos', 'clases', 0, 0, 0, 0, 'canto', 1, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,canto,adultos', 'Y', '', '', 1, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Aprenda t&eacute;cnicas de respiraci&oacute;n y vocalizaci&oacute;n, t&eacute;cnicas de impostaci&oacute;n e interpretaci&oacute;n, micr&oacute;fonos tanto de grabaci&oacute;n como de escenario seg&uacute;n los g&eacute;neros musicales de preferencia del estudiante.</p>\r\n<p>Aprender t&eacute;cnicas de relajaci&oacute;n y alineamiento energ&eacute;tico de chakras en funci&oacute;n del canto.</p>', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Aprender t&eacute;cnicas de respiraci&oacute;n y vocalizaci&oacute;n.</li>\r\n<li>Aprender t&eacute;cnicas de impostaci&oacute;n e interpretaci&oacute;n seg&uacute;n los g&eacute;neros musicales de preferencia del estudiante.</li>\r\n<li>Aprender t&eacute;cnicas de relajaci&oacute;n y alineamiento energ&eacute;tico de chakras en funci&oacute;n del canto.</li>\r\n<li>Encontrar el color natural de la voz y potenciarla con las t&eacute;cnicas aprendidas.</li>\r\n<li>Aprender a dominar los micr&oacute;fonos tanto de grabaci&oacute;n como de escenario.</li>\r\n<li>Desarrollar el o&iacute;do mel&oacute;dico para que el estudiante contin&uacute;e el montaje de otras canciones por su cuenta, una vez finalizado el curso.</li>\r\n<li>Grabar 10 canciones escogidas por el alumno en audio y video, usando pistas facilitadas por la profesora o el estudiante*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Edad: 13 a&ntilde;os en adelante.</li>\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-canto-adultos.jpg', '', '', '', 'Admin', 'sp', '2021-05-25 00:01:01'),
