	(148554821, 'Clase de Canto', 'Gallery', 'clase-de-canto', 'clases', 0, 0, 0, 0, 'canto', 0, 0, '', 0, 0, '', 'clases-canto-ninos', 2, 1, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2015-02-24 19:48:30'),
	(616021734, 'Clases de Guitarra para Niños', 'Article', 'clases-guitarra-ninos', 'clases', 0, 0, 0, 0, 'guitarra', 2, 0, '', 0, 0, 'index-3', '', 1, 1, 'clases,guitarra,ninos,ninas', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Desarrolle la disociaci&oacute;n entre ambas manos, aprende los acordes b&aacute;sicos mayores y menores y su simbolog&iacute;a en cifrado americano.</p>\r\n<p>Aprender los ritmos de acompa&ntilde;amiento b&aacute;sicos de las canciones escogidas por el estudiante.</p>', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Desarrollar la disociaci&oacute;n entre ambas manos.</li>\r\n<li>Aprender los acordes b&aacute;sicos mayores y menores y su simbolog&iacute;a en cifrado americano.</li>\r\n<li>Aprender los ritmos de acompa&ntilde;amiento b&aacute;sicos de las canciones escogidas por el estudiante.</li>\r\n<li>Aprender a leer y a escribir cifrados sencillos</li>\r\n<li>Grabar en audio y video 10 piezas infantiles que escoja el ni&ntilde;o, u otras canciones populares, villancicos, rondas etc*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Edad: 5 a&ntilde;os hasta 12 a&ntilde;os.</li>\r\n<li>Acompa&ntilde;ante adulto ( alg&uacute;n familiar o nana ) durante la clase.</li>\r\n<li>Tener m&iacute;nimo 15 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-guitarra-ninos.jpg', '', '', '', 'Admin', 'sp', '2022-01-12 15:25:07'),
	(1104890971, 'Clase de Guitarra', 'Gallery', 'guitarra-ni-os', 'clases', 0, 0, 0, 0, 'guitarra', 0, 0, '', 0, 0, '', 'clases-guitarra-ninos', 2, 1, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2015-02-24 19:49:11'),
	(654339545, 'Pr&aacute;ctica de grabaci&ntilde;n', 'Gallery', 'pr-ctica-de-grabaci-n', 'clases', 0, 0, 0, 0, 'guitarra', 0, 0, '', 0, 0, '', 'clases-guitarra-ninos', 2, 2, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2022-01-12 15:29:54'),
	(767637914, 'Clases de Bater&iacute;­a para Ni&ntilde;os', 'Article', 'clases-bateria-ninos', 'clases', 0, 0, 0, 0, 'bateria', 2, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,bateria,ninos,ninas', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Adquiera la postura del cuerpo y de las manos para la ejecuci&oacute;n del instrumento. Desarrollar la sicomotricidad gruesa ( piernas y manos ).</p>\r\n<p>Aprender los ritmos de acompa&ntilde;amiento b&aacute;sicos de las canciones escogidas por el estudiante.</p>', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Adquirir la postura del cuerpo y de las manos para la ejecuci&oacute;n del instrumento.</li>\r\n<li>Desarrollar la sicomotricidad gruesa ( piernas y manos ) .</li>\r\n<li>Leer f&oacute;rmulas r&iacute;tmicas sencillas, hasta la subdivisi&oacute;n de semicorcheas</li>\r\n<li>Aprender los ritmos de acompa&ntilde;amiento b&aacute;sicos de las canciones escogidas por el estudiante.</li>\r\n<li>Desarrollar la precisi&oacute;n a trav&eacute;s de los ejercicios de lectura, utilizando el metr&oacute;nomo.</li>\r\n<li>Desarrollar el o&iacute;do r&iacute;tmico para que el estudiante escuche la m&uacute;sica de manera mas consciente y extraiga la bater&iacute;a &uml;cantada&uml; de la canci&oacute;n, por medio de sonidos onomatop&eacute;yicos.</li>\r\n<li>Grabar 10 canciones escogidas por el alumn@ en audio y video, usando pistas facilitadas por la profesora o el estudiante*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Edad: 5 a&ntilde;os hasta 10 a&ntilde;os.</li>\r\n\r\n<li>Acompa&ntilde;ante adulto ( alg&uacute;n familiar o nana ) durante la clase.</li>\r\n<li>En una primera etapa se puede prescindir de la bater&iacute;a y sustituirla en casa por una goma de pr&aacute;ctica, baquetas y 3 cojines. A medida que el estudiante vaya avanzando en la t&eacute;cnica y la coordinaci&oacute;n de manos y pies, puede comprar su bater&iacute;a para practicar .</li>\r\n<li>Tener m&iacute;nimo 15 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 Horas</li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-bateria-ninos.jpg', '', '', '', 'Admin', 'sp', '2021-05-24 23:57:49'),
	(227393974, 'Clase de BaterÃ­a', 'Gallery', 'clase-de-bater-a', 'clases', 0, 0, 0, 0, 'bateria', 0, 0, '', 0, 0, '', 'clases-bateria-ninos', 2, 1, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2015-02-24 19:45:21'),
	(1920463818, 'Clases de Bater&iacute;a para Adultos', 'Article', 'clases-bateria-adultos', 'clases', 0, 0, 0, 0, 'bateria', 1, 0, '', 0, 0, 'index-3', '', 1, 0, 'clase,bateria,adultos', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Desarrolle las t&eacute;cnicas de ejecuci&oacute;n del instrumento a trav&eacute;s de los ejercicios. Aprender a leer y a escribir f&oacute;rmulas r&iacute;tmicas.</p>\r\n<p>Aprender los ritmos de acompa&ntilde;amiento de las canciones escogidas por el estudiante.</p>', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Desarrollar las t&eacute;cnicas de ejecuci&oacute;n del instrumento a trav&eacute;s de los ejercicios.</li>\r\n<li>Aprender a leer y a escribir f&oacute;rmulas r&iacute;tmicas.</li>\r\n<li>Aprender los ritmos de acompa&ntilde;amiento de las canciones escogidas por el estudiante.</li>\r\n<li>Aprender las estructuras que contienen los g&eacute;neros de las canciones que el estudiante elija.</li>\r\n<li>Desarrollar la precisi&oacute;n a trav&eacute;s de los ejercicios de lectura, utilizando el metr&oacute;nomo.</li>\r\n<li>Desarrollar el o&iacute;do r&iacute;tmico para que el estudiante contin&uacute;e el montaje de otras canciones por su cuenta, una vez finalizado el curso.</li>\r\n<li>Desarrollar la improvisaci&oacute;n a trav&eacute;s de ejercicios de montaje con otro instrumento interpretado por la profesora ( piano o guitarra ).</li>\r\n<li>Grabar 10 canciones escogidas por el alumno en audio y video, usando pistas facilitadas por la profesora o el estudiante*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n<li>En una primera etapa se puede prescindir de la bater&iacute;a y sustituirla en casa por una goma de pr&aacute;ctica, baquetas y 3 cojines. A medida que el estudiante vaya avanzando en la t&eacute;cnica y la coordinaci&oacute;n de manos y pies, puede comprar su bater&iacute;a para practicar .</li>\r\n<li>Tener m&iacute;nimo 15 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 Horas</li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-bateria-adultos.jpg', '', '', '', 'Admin', 'sp', '2021-05-24 23:57:49'),
	(33564015, 'Escucha a tu vocal coach: ', 'Gallery', 'bienvenida', 'recepcion-pagos', 0, 0, 3, 0, '', 0, 0, '', 0, 0, '', 'bienvenido-a-la-escuela-de-musica-adriana-granobles', 2, 0, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2020-09-24 19:03:54'),
	(1452100194, 'Nuevos productos', 'Article', 'nuevos-productos', 'noticias', 0, 0, 1, 0, '', 0, 0, '', 0, 0, 'index-2', '', 1, 0, 'nuevos,productos', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>intro contenido</p>', '<p>contenido largo</p>', '', '', '', '', '', '', '', '', '', '', 'Adriana', 'sp', '2020-09-24 16:49:45'),
	(343787063, 'Â¿Te gustarÃ­a contribuir a la sanaciÃ³n del planeta con tu voz y tu energÃ­a?', 'Gallery', 'video', 'coro-universal-del-amor', 0, 0, 2, 0, '', 0, 0, '', 0, 0, '', 'coro-universal-del-amor', 2, 0, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2020-10-14 19:46:00'),
	(1427456022, 'Coro Universal del Amor', 'ShortArticle', 'coro-universal-del-amor', 'coro-universal-del-amor', 0, 0, 1, 0, '', 0, 0, '', 0, 0, 'Full-Width', '', 1, 0, 'coro,universal,del,amor', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>El Coro Universal del Amor es un proyecto art&iacute;stico que a la vez es una escuela de canto con un prop&oacute;sito claro en su aporte a la humanidad, no solo en conocimientos musicales, sino tambi&eacute;n con repercusi&oacute;n a nivel mundial por sus mensajes de amor y conciencia que contiene su repertorio.</p>\r\n<p>Comenzamos<span class="Apple-converted-space">&nbsp; </span>a recibir a los integrantes el 12 de Octubre del a&ntilde;o 2020 Daremos una formaci&oacute;n gratuita <strong>durante 1 mes a partir del 19 de Octubre.</strong></p>\r\n<p style="text-align: center;"><strong><em>No es solamente un coro&hellip;es una Escuela de Canto&nbsp;diferente!</em></strong></p>\r\n<ul class="list1">\r\n<li>Aprende a leer una partitura y a cantar de manera t&eacute;cnica.</li>\r\n<li>Participar&aacute;s en la realizaci&oacute;n de un video-mosaico en 3D que lanzar&aacute; la empresa de producci&oacute;n musical ADRIANA GRANOBLES.</li>\r\n<li>Conoce gente de todas partes del mundo.</li>\r\n<li>No te quedes fuera del nuevo concepto musical de coro que revolucionar&aacute; el mundo.</li>\r\n</ul>\r\n<p><strong>Horario</strong>: LUNES, MI&Eacute;RCOLES Y VIERNES a las 12:00 P.M Hora Colombia , 7:00 P.M. Hora Espa&ntilde;a</p>\r\n<p>La lectura de partituras se ense&ntilde;ar&aacute; de manera intuitiva, ya que leer correctamente una partitura requiere de un estudio profundo de la gram&aacute;tica musical.</p>\r\n<p>A trav&eacute;s de un grupo privado de Facebook, comenzaremos:</p>\r\n<blockquote>\r\n<p>*LUNES*: Gram&aacute;tica Musical ( b&aacute;sica ) Con Rub&eacute;n D&iacute;az de M&eacute;xico<span class="Apple-converted-space">&nbsp;</span></p>\r\n<p>*MI&Eacute;RCOLES*: Ensayo ( Mujeres con Adriana Granobles y hombres con Rub&eacute;n D&igrave;az</p>\r\n<p>*VIERNES*:T&eacute;cnica Vocal con Adriana Granobles.</p>\r\n<p>La primera canci&oacute;n que vamos a montar se llama &ldquo;AMOR Y FELICIDAD&rdquo; en arreglo vocal De Diego Luna. Compartiremos por nuestra plataforma privada de Facebook&nbsp;los audios y partituras para que puedan ir estudiando el material, a partir del pr&oacute;ximo lunes 12 de Octubre.</p>\r\n</blockquote>\r\n<p style="text-align: left;"><strong>Este es el link de nuestro grupo privado&nbsp;de whatsapp en donde te comunicaremos todos los detalles:&nbsp;<a href="https://chat.whatsapp.com/GlkM5CGJfh29IZW2CXvIdG">GRUPO PRIVADO DE WHATSAPP</a></strong></p>\r\n<p style="text-align: left;">Todas las sesiones quedar&aacute;n grabadas&nbsp;en nuestro grupo privado de Facebook&nbsp;por si no puedes conectarte. Tendremos una sesi&oacute;n por zoom el domingo 8 de Noviembre en donde compartiremos inquietudes y revisaremos aleatoriamente entre los integrantes, las partes de cada cual.</p>\r\n<p style="text-align: left;">Despu&eacute;s de esta sesi&oacute;n, tendr&aacute;n una semana cada uno para entregar su v&iacute;deo personal hecho con su celular, cantando su parte . Nosotros los reunimos y haremos la producci&oacute;n de un v&iacute;deo de todos en formato 3D.</p>\r\n<p>&nbsp;</p>\r\n<p>TE ESPERAMOS!</p>\r\n<p>Adriana Granobles<br />Directora General</p>\r\n<p>&nbsp;</p>', '', '', '', '', '', '', '', '', '', '', '', 'Adriana', 'sp', '2020-10-19 16:54:26'),
	(1829275764, 'Te invitamos a una masterclass de canto GRATIS!', 'Gallery', 'te-invitamos-a-una-masterclass-de-canto-gratis', 'masterclass-de-canto-gratis', 0, 0, 1, 1, '', 0, 0, '', 0, 0, '', '', 1, 0, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Adriana', 'sp', '2020-10-15 12:46:01'),
	(1630469556, 'Clases de Piano para Adultos', 'Article', 'clases-piano-adultos', 'clases', 0, 0, 0, 0, 'piano', 1, 0, '', 0, 0, 'index-3', '', 1, 1, 'clases,piano,adultos', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Desarrolle las t&eacute;cnicas de ejecuci&oacute;n del instrumento a trav&eacute;s de los ejercicios. Aprender de forma te&oacute;rica y pr&aacute;ctica las escalas mayores y menores.</p>\r\n<p>Aprender las leyes fundamentales de la armon&iacute;a tradicional de la m&uacute;sica popular.</p>', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Desarrollar las t&eacute;cnicas de ejecuci&oacute;n del instrumento a trav&eacute;s de los ejercicios.</li>\r\n<li>Aprender los ritmos de acompa&ntilde;amiento de las canciones escogidas por el estudiante.</li>\r\n<li>Aprender de forma te&oacute;rica y pr&aacute;ctica las escalas mayores y menores y la funcionalidad de los grados que contienen.</li>\r\n<li>Aprender las leyes fundamentales de la armon&iacute;a tradicional de la m&uacute;sica popular.</li>\r\n<li>Aprender a leer y a escribir cifrados.</li>\r\n<li>Aprender las estructuras de los g&eacute;neros de las canciones que el estudiante elija.</li>\r\n<li>Desarrollar el o&iacute;do arm&oacute;nico para que el estudiante contin&uacute;e el montaje de otras canciones por su cuenta, una vez finalizado el curso.</li>\r\n<li>Grabar 10 canciones escogidas por el alumno en audio y video*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Tener instrumento para practicar.</li>\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-piano-adultos.jpg', '', '', '', 'Admin', 'sp', '2021-05-25 00:01:01'),
	(11955622, 'Clases de Piano para Ni&ntilde;os', 'Article', 'clases-piano-ninos', 'clases', 0, 0, 0, 0, 'piano', 2, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,piano,nino,ninass', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Adquiera la postura del cuerpo y de las manos para la ejecuci&oacute;n del instrumento. Aprenda de forma pr&aacute;ctica las escalas mayores y su digitaci&oacute;n.</p>\r\n<p>Aprenda los encadenamientos I IV V con ambas manos en todas las tonalidades mayores.</p>', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Adquirir la postura del cuerpo y de las manos para la ejecuci&oacute;n del instrumento.</li>\r\n<li>Aprender de forma pr&aacute;ctica las escalas mayores y su digitaci&oacute;n, primero manos separadas y luego juntas.</li>\r\n<li>Aprender los encadenamientos I IV V con ambas manos en todas las tonalidades mayores.</li>\r\n<li>Leer partituras sencillas con clave de sol y fa</li>\r\n<li>Grabar en audio y video 10 piezas infantiles que escoja el ni&ntilde;o del m&eacute;todo b&aacute;sico de Bastien, o de otras canciones populares, villancicos, rondas etc*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Tener instrumento para practicar.</li>\r\n<li>Edad: 5 a&ntilde;os hasta 10 a&ntilde;os.</li>\r\n<li>Acompa&ntilde;ante adulto ( alg&uacute;n familiar o nana ) durante la clase.</li>\r\n<li>Entrevista con la profesora para evaluar los intereses y aptitudes musicales del alumno, y para que &eacute;l a su vez conozca el estudio de grabaci&oacute;n y los ejemplos de audio y video de otros estudiantes. Separa tu cita para realizarte la valoraci&oacute;n de una hora por un valor de $150.000. Llama al (1) 814-7114 &oacute; Whatsapp +57 321 240 9712*.</li>\r\n<li>Tener m&iacute;nimo 15 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-piano-ninos.jpg', '', '', '', 'Admin', 'sp', '2022-01-12 15:30:30'),
	(1167255317, 'Clase de Piano', 'Gallery', 'clase-de-piano', 'clases', 0, 0, 0, 0, 'piano', 0, 0, '', 0, 0, '', 'clases-piano-ninos', 2, 1, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2015-02-25 16:01:03'),
	(542943237, 'Clase de Piano Skype', 'Gallery', 'clase-de-piano-skype', 'clases', 0, 0, 0, 0, 'piano', 0, 0, '', 0, 0, '', 'clases-piano-ninos', 2, 1, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2015-02-25 16:14:34'),
	(1235224765, 'Clases de percusi&oacute;n para adultos', 'Article', 'clases-percusion-adultos', 'clases', 0, 0, 0, 0, 'percusion', 1, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,percusion,adultos', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Desarrolle las t&eacute;cnicas de ejecuci&oacute;n para instrumentos de membrana tales como el bong&oacute;, conga, llamador y alegre, as&iacute; como tambi&eacute;n para instrumentos de baquetas tales como la timbaleta y la tambora, a trav&eacute;s de los ejercicios.</p>\r\n<p>Aprender las estructuras que contienen los g&eacute;neros de las canciones que el estudiante elija.</p>', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Desarrollar las t&eacute;cnicas de ejecuci&oacute;n para instrumentos de membrana tales como el bong&oacute;, conga, llamador y alegre, as&iacute; como tambi&eacute;n para instrumentos de baquetas tales como la timbaleta y la tambora, a trav&eacute;s de los ejercicios.</li>\r\n<li>Aprender a leer y a escribir f&oacute;rmulas r&iacute;tmicas.</li>\r\n<li>Aprender los ritmos de acompa&ntilde;amiento de las canciones escogidas por el estudiante.</li>\r\n<li>Aprender las estructuras que contienen los g&eacute;neros de las canciones que el estudiante elija.</li>\r\n<li>Desarrollar la precisi&oacute;n a trav&eacute;s de los ejercicios de lectura, utilizando el metr&oacute;nomo.</li>\r\n<li>Desarrollar el o&iacute;do r&iacute;tmico para que el estudiante contin&uacute;e el montaje de otras canciones por su cuenta, una vez finalizado el curso.</li>\r\n<li>Desarrollar la improvisaci&oacute;n a trav&eacute;s de ejercicios de montaje con otro instrumento interpretado por la profesora ( piano, bater&iacute;a o guitarra ).</li>\r\n<li>Grabar 10 canciones escogidas por el alumno en audio y video, usando pistas facilitadas por la profesora o el estudiante*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n<li>Tener instrumento para practicar.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-percusion-adultos.jpg', '', '', '', 'Admin', 'sp', '2021-05-25 00:01:01'),
	(185232802, 'Clases de percusi&oacute;n para ni&ntilde;os', 'Article', 'clases-percusion-ninos', 'clases', 0, 0, 0, 0, 'percusion', 2, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,percusion,ninos,ninas', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Desarrollar la sicomoticidad del ni&ntilde;o con juegos r&iacute;tmicos a uno y dos niveles.</p>\r\n<p>Desarrollar las t&eacute;cnicas de ejecuci&oacute;n para instrumentos de membrana tales como el bong&oacute;, conga, llamador y alegre, as&iacute; como tambi&eacute;n para instrumentos de baquetas tales como la timbaleta y la tambora, a trav&eacute;s de los ejercicios.</p>', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Desarrollar la sicomoticidad del ni&ntilde;o con juegos r&iacute;tmicos a uno y dos niveles.</li>\r\n<li>Desarrollar las t&eacute;cnicas de ejecuci&oacute;n para instrumentos de membrana tales como el bong&oacute;, conga, llamador y alegre, as&iacute; como tambi&eacute;n para instrumentos de baquetas tales como la timbaleta y la tambora, a trav&eacute;s de los ejercicios.</li>\r\n<li>Aprender a leer y a escribir f&oacute;rmulas r&iacute;tmicas.</li>\r\n<li>Aprender los ritmos de acompa&ntilde;amiento de las canciones escogidas por el estudiante.</li>\r\n<li>Aprender las estructuras que contienen los g&eacute;neros de las canciones que el estudiante elija.</li>\r\n<li>Desarrollar la precisi&oacute;n a trav&eacute;s de los ejercicios de lectura, utilizando el metr&oacute;nomo.</li>\r\n<li>Desarrollar el o&iacute;do r&iacute;tmico para que el estudiante contin&uacute;e el montaje de otras canciones por su cuenta, una vez finalizado el curso.</li>\r\n<li>Desarrollar la improvisaci&oacute;n a trav&eacute;s de ejercicios de montaje con otro instrumento interpretado por la profesora ( piano, bater&iacute;a o guitarra ).</li>\r\n<li>Grabar 10 canciones escogidas por el alumno en audio y video, usando pistas facilitadas por la profesora o el estudiante*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n<li>Acompa&ntilde;ante adulto (alg&uacute;n familiar o nana) durante la clase.</li>\r\n<li>Tener instrumento para practicar.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-percusion-ninos.jpg', '', '', '', 'Admin', 'sp', '2022-01-12 15:31:36'),
	(103000693, 'Clases de bajo para adultos', 'Article', 'clases-bajo-adultos', 'clases', 0, 0, 0, 0, 'bajo', 1, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,bajo,adultos', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Desarrollar el o&iacute;do mel&oacute;dico para que el estudiante contin&uacute;e el montaje de otras canciones por su cuenta, una vez finalizado el curso.</li>\r\n<li>Grabar 10 canciones escogidas por el alumno en audio y video, usando pistas facilitadas por la profesora o el estudiante*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Edad: 13 a&ntilde;os en adelante.</li>\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2021-05-25 00:01:01'),
	(1637316104, 'Clases de bajo para ni&ntilde;os', 'Article', 'clases-bajo-ninos', 'clases', 0, 0, 0, 0, 'bajo', 2, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,bajo,ninos,ninas', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Generar en el ni&ntilde;o seguridad en s&iacute; mismo para que se exprese libremente.</li>\r\n<li>Desarrollar el o&iacute;do mel&oacute;dico a trav&eacute;s de los ejercicios.</li>\r\n<li>Entrenar al ni&ntilde;o espiritualmente para que aprenda a tener un espacio en donde se conecte consigo mismo y su energ&iacute;a , por medio de ejercicios sencillos de meditaci&oacute;n y relajaci&oacute;n.</li>\r\n<li>Grabar 10 canciones escogidas por el alumno en audio y video, usando pistas facilitadas por la profesora*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Edad: 5 a&ntilde;os hasta 12 a&ntilde;os.</li>\r\n<li>Acompa&ntilde;ante adulto ( alg&uacute;n familiar o nana ) durante la clase.</li>\r\n\r\n<li>Tener m&iacute;nimo 15 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2022-01-12 15:31:51'),
	(918899437, 'Clases de flauta traversa para adultos', 'Article', 'clases-flauta-traversa-adultos', 'clases', 0, 0, 0, 0, 'flauta-traversa', 1, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,flauta,traversa,adultos', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Desarrollar el o&iacute;do mel&oacute;dico para que el estudiante contin&uacute;e el montaje de otras canciones por su cuenta, una vez finalizado el curso.</li>\r\n<li>Grabar 10 canciones escogidas por el alumno en audio y video, usando pistas facilitadas por la profesora o el estudiante*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Edad: 13 a&ntilde;os en adelante.</li>\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2021-05-25 00:01:01'),
	(454634981, 'Clases de flauta traversa para ni&ntilde;os', 'Article', 'clases-flauta-traversa-ninos', 'clases', 0, 0, 0, 0, 'flauta-traversa', 2, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,flauta,traversa,ninos,ninas', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Generar en el ni&ntilde;o seguridad en s&iacute; mismo para que se exprese libremente.</li>\r\n<li>Desarrollar el o&iacute;do mel&oacute;dico a trav&eacute;s de los ejercicios.</li>\r\n<li>Entrenar al ni&ntilde;o espiritualmente para que aprenda a tener un espacio en donde se conecte consigo mismo y su energ&iacute;a , por medio de ejercicios sencillos de meditaci&oacute;n y relajaci&oacute;n.</li>\r\n<li>Grabar 10 canciones escogidas por el alumno en audio y video, usando pistas facilitadas por la profesora*.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Edad: 5 a&ntilde;os hasta 12 a&ntilde;os.</li>\r\n<li>Acompa&ntilde;ante adulto ( alg&uacute;n familiar o nana ) durante la clase.</li>\r\n<li>Tener m&iacute;nimo 15 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2022-01-12 15:33:29'),
	(196199611, 'Clases de teor&iacute;a musical para adultos', 'Article', 'clases-teoria-musical-adultos', 'clases', 0, 0, 0, 0, 'teoria-musical', 1, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,teoria,musical,adultos', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Ritmo, melod&iacute;a, desarrollo auditivo, armon&iacute;a, mapeado de canciones.</p>', '<h3>TEMAS</h3>\r\n<div class="row">\r\n<article class="col-lg-6 col-md-6 col-sm-6">\r\n<h4>Ritmo</h4>\r\n<ol class="listado">\r\n<li>Las figuras de duraci&oacute;n</li>\r\n<li>Ligaduras y puntillo</li>\r\n<li>S&iacute;ncopa y contratiempo</li>\r\n<li>El tresillo</li>\r\n<li>El comp&aacute;s</li>\r\n<li>La cifra indicadora de comp&aacute;s</li>\r\n<li>Lecturas r&iacute;tmicas</li>\r\n<li>Dictados r&iacute;tmicos</li>\r\n</ol></article>\r\n<article class="col-lg-6 col-md-6 col-sm-6">\r\n<h4>Melod&iacute;a</h4>\r\n<ol type="1">\r\n<li>Las notas musicales</li>\r\n<li>El pentagrama y sus claves</li>\r\n<li>La escala Mayor diat&oacute;nica</li>\r\n<li>Alteraciones</li>\r\n<li>Intervalos</li>\r\n<li>Lectura hablada en clave de sol y fa</li>\r\n<li>Dictados mel&oacute;dicos</li>\r\n<li>Escalas menores</li>\r\n<li>Signos de repetici&oacute;n</li>\r\n</ol></article>\r\n</div>\r\n<div class="row">\r\n<article class="col-lg-12 col-md-12 col-sm-12">\r\n<h4>Desarrollo auditivo</h4>\r\n<ol class="listado">\r\n<li>Intervalos simples</li>\r\n<li>Diferenciaci&oacute;n entre acorde mayor y menor</li>\r\n<li>Diferenciaci&oacute;n entre acordes mayores con 7a mayor y acordes mayores con 7a. menor</li>\r\n<li>Diferenciaci&oacute;n entre acordes suspendidos y aumentados</li>\r\n<li>Diferenciaci&oacute;n entre acordes menores con 7a mayor y s&eacute;ptima menor</li>\r\n<li>Diferenciaci&oacute;n entre acordes disminuidos y semidisminuidos</li>\r\n<li>Diferenciaci&oacute;n entre acordes novena de dominante y mayores con 7a y 9a mayor</li>\r\n<li>Reconocimiento auditivo de instrumentos musicales de m&uacute;sica popular y sinf&oacute;nica</li>\r\n<li>Reconocimiento de grados en canciones populares</li>\r\n</ol></article>\r\n</div>\r\n<div class="row">\r\n<article class="col-lg-6 col-md-6 col-sm-6">\r\n<h4>Armon&iacute;a</h4>\r\n<ol class="listado">\r\n<li>La tonalidad</li>\r\n<li>Armaduras</li>\r\n<li>Triadas que se forman sobre cada grado de una escala Mayor y una escala menor</li>\r\n<li>Transportaci&oacute;n</li>\r\n<li>Inversi&oacute;n de acordes</li>\r\n<li>Progresiones arm&oacute;nicas</li>\r\n<li>Las cuatriadas en tonalidad mayor y menor</li>\r\n<li>Lectura de cifrados en el piano</li>\r\n<li>Lectura de partituras analizando armon&iacute;a y forma musical</li>\r\n</ol></article>\r\n<article class="col-lg-6 col-md-6 col-sm-6">\r\n<h4>Mapeado de canciones</h4>\r\n<ol class="listado">\r\n<li>Escritura de compases de toda la canci&oacute;n</li>\r\n<li>Escritura de forma musical, diferenciaci&oacute;n de secciones ( Intro, estrofa, pre-coro, coro, interludios, coda ).</li>\r\n<li>Escritura de patrones principales de bater&iacute;a</li>\r\n<li>Escritura de patrones del bajo</li>\r\n<li>Escritura de entradas de instrumentos asociados al arreglo</li>\r\n<li>Escritura de frases repetidas o motivos</li>\r\n<li>Escritura de los acordes de la canci&oacute;n</li>\r\n</ol></article>\r\n</div>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n<li>Tener un teclado de cualquier tama&ntilde;o.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 Horas</li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-teoria-musical-adultos.jpg', '', '', '', 'Admin', 'sp', '2021-05-24 23:57:49'),
	(1519528851, 'La Presidenta', 'Other', 'la-presidenta', 'servicios', 0, 0, 0, 0, '', 0, 0, '', 0, 0, 'Full-Width', 'coaching-ontologico', 2, 1, 'la,presidenta', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<h3 align="center">"La Presidenta" El éxito de mi vida</h3><p align="center"> <img src="https://adrianagranobles.com/images/articles/Screenshot_libro-katia.jpg" width="190px"><form action="https://www.paypal.com/cgi-bin/webscr" method="post"><div style="text-align: center;"><input id="submit" class="btn-default btn2" alt="Make payments with PayPal - it\'s fast, free and secure!" name="submit" type="submit" value="Comprar Ahora"  /></div> <input name="cmd" type="hidden" value="_s-xclick" /> <input name="hosted_button_id" type="hidden" value="V5GSMR9APWAFU" /> <img src="https://www.paypalobjects.com/en_US/i/scr/pixel.gif" alt="" width="1" height="1" border="0" /></form></p>', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2021-05-25 00:51:16'),
	(1977672741, 'Clases de teor&iacute;a musical para ni&ntilde;os', 'Article', 'clases-teoria-musical-ninos', 'clases', 0, 0, 0, 0, 'teoria-musical', 2, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,teoria,musical,ninos,ninas', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Ritmo, melod&iacute;a, desarrollo auditivo, armon&iacute;a, mapeado de canciones.</p>', '<h3>TEMAS</h3>\r\n<div class="row">\r\n<article class="col-lg-6 col-md-6 col-sm-6">\r\n<h4>Ritmo</h4>\r\n<ol class="listado">\r\n<li>Las figuras de duraci&oacute;n</li>\r\n<li>Ligaduras</li>\r\n<li>Contratiempo</li>\r\n<li>El tresillo</li>\r\n<li>El comp&aacute;s</li>\r\n<li>La cifra indicadora de comp&aacute;s</li>\r\n<li>Lecturas r&iacute;tmicas</li>\r\n<li>Dictados r&iacute;tmicos</li>\r\n</ol></article>\r\n<article class="col-lg-6 col-md-6 col-sm-6">\r\n<h4>Melod&iacute;a</h4>\r\n<ol class="listado">\r\n<li>Las notas musicales</li>\r\n<li>El pentagrama y la clave de sol</li>\r\n<li>La escala Mayor diat&oacute;nica</li>\r\n<li>Lectura hablada en clave de sol</li>\r\n<li>Dictados mel&oacute;dicos</li>\r\n<li>Signos de repetici&oacute;n</li>\r\n</ol></article>\r\n</div>\r\n<div class="row">\r\n<article class="col-lg-6 col-md-6 col-sm-6">\r\n<h4>Armon&iacute;a</h4>\r\n<ol class="listado">\r\n<li>La tonalidad.</li>\r\n<li>Armaduras de G, D, A, E y F.</li>\r\n<li>Triadas que se forman sobre cada grado de una escala Mayor.</li>\r\n</ol></article>\r\n<article class="col-lg-6 col-md-6 col-sm-6">\r\n<h4>Desarrollo auditivo</h4>\r\n<ol class="listado">\r\n<li>Intervalos simples de 2a Mayor y menor, 3a Mayor y menor, 4a., 5a. y 8va. justa.</li>\r\n<li>Diferenciaci&oacute;n entre acorde mayor y menor.</li>\r\n<li>Diferenciaci&oacute;n entre acordes mayores con 7a mayor y acordes mayores con 7a. menor.</li>\r\n<li>Diferenciaci&oacute;n de acordes suspendidos.</li>\r\n<li>Reconocimiento auditivo de instrumentos musicales de m&uacute;sica popular y sinf&oacute;nica.</li>\r\n</ol></article>\r\n</div>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n<li>Acompa&ntilde;ante adulto (alg&uacute;n familiar o nana) durante la clase.</li>\r\n<li>Tener un teclado de cualquier tama&ntilde;o.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 Horas</li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-teoria-musical-ninos.jpg', '', '', '', 'Admin', 'sp', '2022-01-12 15:32:22'),
	(1486966819, 'Clase de teorÃ­a musical', 'Gallery', 'clase-de-teor-a-musical', 'clases', 0, 0, 0, 0, 'teoria-musical', 0, 0, '', 0, 0, '', 'clases-teoria-musical-ninos', 2, 1, '', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '', '', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2015-02-25 18:18:39'),
	(1371171158, 'Clases de composici&oacute;n y producci&oacute;n musical para adultos', 'Article', 'clases-composicion-y-produccion-musical-adultos', 'clases', 0, 0, 0, 0, 'composicion-y-produccion-musical', 1, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,composicion,produccion,musical,adultos', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Desarrollar la capacidad de escribir letras para canciones con ejercicios de creaci&oacute;n escrita. Analizar letras, armon&iacute;a e instrumentaci&oacute;n de 10 canciones escogidas por el estudiante en los g&eacute;neros que desea componer.</p>\r\n<p>Aprender progresiones arm&oacute;nicas t&iacute;picas de los g&eacute;neros en los que est&aacute; interesado.</p>', '<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Desarrollar la capacidad de escribir letras para canciones con ejercicios de creaci&oacute;n escrita.</li>\r\n<li>Analizar letras, armon&iacute;a e instrumentaci&oacute;n de 10 canciones escogidas por el estudiante en los g&eacute;neros que desea componer*.</li>\r\n<li>Desarrollar el o&iacute;do para diferenciar las secciones de cualquier canci&oacute;n popular.</li>\r\n<li>Aprender progresiones arm&oacute;nicas t&iacute;picas de los g&eacute;neros en los que est&aacute; interesado.</li>\r\n<li>Conocer sobre la construcci&oacute;n de la melod&iacute;a y sus caracter&iacute;sticas dentro de la forma musical.</li>\r\n<li>Improvisaci&oacute;n mel&oacute;dica con estructuras arm&oacute;nicas comunes.</li>\r\n<li>Conocer las f&oacute;rmulas b&aacute;sicas de los ritmos de las canciones escogidas. Saber cantar, con sonidos onomatop&eacute;yicos, lo que escucha en la bater&iacute;a o percusiones.</li>\r\n<li>Conocer el movimiento del bajo seg&uacute;n el g&eacute;nero de la canci&oacute;n, y su correspondencia arm&oacute;nica.</li>\r\n<li>Aprender los principios b&aacute;sicos de la orquestaci&oacute;n seg&uacute;n los g&eacute;neros en que el alumno desea profundizar.</li>\r\n<li>Aprender a hacer una maqueta con los siguientes elementos en un software musical: bater&iacute;a, bajo, armon&iacute;a ( en piano o guitarra ), arreglos mel&oacute;dicos sencillos con cuerdas, flauta, saxo etc.</li>\r\n<li>Grabar 10 composiciones del alumno en audio y video.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Conocer la teor&iacute;a musical b&aacute;sica ( ver programa de <a href="../teoria-musical/clases-teoria-musical-adultos">TEORIA MUSICAL ADULTOS</a> )</li>\r\n<li>Tocar un instrumento arm&oacute;nico de forma b&aacute;sica, tal como la guitarra o el piano ( ver programa de <a href="../guitarra/clases-guitarra-adultos">GUITARRA PARA ADULTOS</a> o <a href="../piano/clases-piano-adultos">PIANO ADULTOS</a> )</li>\r\n<li>Tener instrumento arm&oacute;nico para practicar ( Guitarra o piano )</li>\r\n<li>Tener computador con software musical para hacer programaciones.</li>\r\n\r\n<li>Tener m&iacute;nimo 30 minutos diarios de pr&aacute;ctica para desarrollar los ejercicios en casa.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-composicion-ninos.jpg', '', '', '', 'Admin', 'sp', '2021-05-25 00:01:01'),
	(678144853, 'Clases de composición y produccion musical para niños', 'Article', 'clases-composicion-y-produccion-musical-ninos', 'clases', 0, 0, 0, 0, 'composicion-y-produccion-musical', 2, 0, '', 0, 0, 'index-3', '', 1, 0, 'clases,composicion,produccion,musical,ninos,ninas', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>A trav&eacute;s de este curso, el ni&ntilde;o despierta a la creaci&oacute;n literaria y musical, ayudado por un software de producci&oacute;n que le da la posibilidad de acceder a diferentes timbres de instrumentos. Hacemos lecturas de cuentos infantiles que despu&eacute;s el ni&ntilde;o resume con sus expresiones naturales, grab&aacute;ndolas para posteriormente escucharse y crear la banda sonora de los cuentos.</p>', '<p>A trav&eacute;s de este curso, el ni&ntilde;o despierta a la creaci&oacute;n literaria y musical, ayudado por un software de producci&oacute;n que le da la posibilidad de acceder a diferentes timbres de instrumentos. Hacemos lecturas de cuentos infantiles que despu&eacute;s el ni&ntilde;o resume con sus expresiones naturales, grab&aacute;ndolas para posteriormente escucharse y crear la banda sonora de los cuentos.</p>\r\n<p>Escribe sus propias historias, se le motiva a escribir sobre su entorno y tambi&eacute;n a expresar sus sentimientos de forma escrita.</p>\r\n<h3>OBJETIVOS ESPECIFICOS</h3>\r\n<ul class="list1">\r\n<li>Desarrollar la capacidad creativa en el ni&ntilde;o.</li>\r\n<li>Aprender sobre los diferentes timbres de los instrumentos musicales, asoci&aacute;ndolos a personajes de cuentos, animales o emociones desde la percepci&oacute;n del ni&ntilde;o.</li>\r\n<li>Desarrollar el o&iacute;do para diferenciar instrumentos musicales.</li>\r\n<li>Desarrollar la capacidad de comprensi&oacute;n de cuentos o historias.</li>\r\n<li>Improvisaci&oacute;n mel&oacute;dica con estructuras arm&oacute;nicas sencillas.</li>\r\n<li>Grabar 5 cuentos con musicalizaci&oacute;n creada por el ni&ntilde;o (audio y video).</li>\r\n<li>Grabar 5 canciones cuya letra y melod&iacute;a son creadas por el ni&ntilde;o, y acompa&ntilde;adas por una pista sencilla de guitarra o piano (audio y video).</li>\r\n</ul>\r\n<h3>PRE-REQUISITOS</h3>\r\n<ul class="list1">\r\n<li>Edad: 5 a&ntilde;os hasta 10 a&ntilde;os.</li>\r\n<li>Acompa&ntilde;ante adulto (alg&uacute;n familiar o nana) durante la clase.</li>\r\n</ul>\r\n<p><em>*Solo para clases presenciales.</em></p>\r\n<p>&nbsp;</p>\r\n<h3>DURACION</h3>\r\n<ul class="list1">\r\n<li>48 horas <em>(Solo clases presenciales)</em></li>\r\n</ul>\r\n<h3>METODOLOGIA</h3>\r\n<ul class="list1">\r\n<li><a href="../metodologia">Leer Mas</a></li>\r\n</ul>\r\n<h3>PRECIOS</h3>\r\n<ul class="list1">\r\n<li><a href="../../precios/">Leer Mas</a></li>\r\n</ul>\r\n<h3>CONTACTO</h3>\r\n<ul class="list1">\r\n<li><a href="../../contacto/">Formulario de Contacto</a></li>\r\n</ul>', '', '', '', '', '', '', 'image-composicion-ninos.jpg', '', '', '', 'Admin', 'sp', '2022-01-12 15:23:40'),
	(2097597613, 'canto', 'Article', 'canto', 'clases', 0, 0, 0, 0, 'canto', 0, 0, '', 0, 0, 'index-2', '', 1, 0, 'canto', 'Y', '', 'slider', 5, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Clases para adultos</p>', '<p>Aprenda t&eacute;cnicas de respiraci&oacute;n y vocalizaci&oacute;n, t&eacute;cnicas de impostaci&oacute;n e interpretaci&oacute;n,&nbsp;micr&oacute;fonos tanto de grabaci&oacute;n como de escenario.</p>', 'Técnicas de respiración y vocalización', '/clases/canto/clases-canto-adultos', '', '', '', 'image-canto-big.jpg', 'image-canto-small.jpg', '', '', '', 'Admin', 'sp', '2021-02-19 18:49:30'),
	(1598074797, 'Guitarra', 'Article', 'guitarra', 'clases', 0, 0, 0, 0, 'guitarra', 0, 0, '', 0, 0, 'Full-Width', '', 1, 0, 'guitarra', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Clases para adultos</p>', '<p>Desarrolle las t&eacute;cnicas de ejecuci&oacute;n del instrumento a trav&eacute;s de los ejercicios, ritmos de acompa&ntilde;amiento de las canciones escogidas por el estudiante.</p>', '', '/clases/guitarra/clases-guitarra-adultos', '', '', '', 'picture1.jpg', 'image-guitarra-small.jpg', '', '', '', 'Admin', 'sp', '2018-05-04 02:51:29'),
	(1750540312, 'Bateria', 'Article', 'bateria', 'clases', 0, 0, 0, 0, 'bateria', 0, 0, '', 0, 0, 'Full-Width', '', 1, 0, 'bateria', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Clases para adultos</p>', '<p>Desarrolle las t&eacute;cnicas de ejecuci&oacute;n del instrumento a trav&eacute;s de los ejercicios. Aprender a leer y a escribir f&oacute;rmulas r&iacute;tmicas.</p>', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2015-02-26 23:24:26'),
	(1330048733, 'Piano', 'Article', 'piano', 'clases', 0, 0, 0, 0, 'piano', 0, 0, '', 0, 0, 'Full-Width', '', 1, 0, 'piano', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Clases para ni&ntilde;os</p>', '<p>Adquiera la postura del cuerpo y de las manos para la ejecuci&oacute;n del instrumento. Aprenda de forma pr&aacute;ctica las escalas mayores y su digitaci&oacute;n.</p>', '', '/clases/piano/clases-piano-ninos', '', '', '', '', 'image-piano-small.jpg', '', '', '', 'Admin', 'sp', '2018-05-04 02:51:29'),
