	(647556544, 'Composici&oacute;n', 'Article', 'composicion', 'estudio-de-grabacion', 0, 0, 1, 1, '', 0, 0, '', 0, 0, 'index-3', '', 1, 0, 'composicion', 'Y', '', '', 0, '', 0, '', 0, '', 0, '', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', '<p>Composici&oacute;n artistica y comercial</p>', '<h3>Composici&oacute;n Art&iacute;stica:</h3>\r\n<ol class="listado">\r\n<li>Composici&oacute;n de canciones</li>\r\n<li>Composici&oacute;n de m&uacute;sica incidental para:\r\n<ul class="list1">\r\n<li>cine</li>\r\n<li>videos institucionales</li>\r\n<li>documentales</li>\r\n<li>obras teatrales</li>\r\n<li>exposiciones de arte o expresiones art&iacute;sticas multimedia.</li>\r\n<li>teatro</li>\r\n</ul>\r\n</li>\r\n</ol>\r\n<h3>Composici&oacute;n Comercial:</h3>\r\n<ol class="listado">\r\n<li>Jingles</li>\r\n<li>Loops para web sites</li>\r\n<li>Dise&ntilde;o Sonoro:\r\n<ul class="list1">\r\n<li>Logos auditivos</li>\r\n<li>Sonidos concretos</li>\r\n<li>Blips</li>\r\n</ul>\r\n</li>\r\n</ol>', '', '', '', '', '', '', '', '', '', '', 'Admin', 'sp', '2021-03-25 20:41:33'),
