	(104, 'Form', 'Response', 'Y', 'Form Response', '#|question=Register|name=full_name|type=textfield|required=true|displayname=Enter your Full Name:|initialvalue=;\r\n#|question=|name=age|type=textfield|required=true|displayname=Age:|initialvalue=;\r\n#|question=|name=email|type=textfield|required=true|displayname=Enter your e-mail:|initialvalue=;\r\n#|question=Emergency Contact Info|name=emergency_contact_name|type=textfield|required=true|displayname=Enter your Emergency Contact Info:|initialvalue=;\r\n#|question=|name=home_phone|type=textfield|required=true|displayname=Enter Emergency Home Phone:|initialvalue=;\r\n#|question=|name=cell_phone|type=textfield|required=true|displayname=Enter Emergency Cell Phone:|initialvalue=;\r\n#|question=Please Select:|name=walker_runner|type=radio|required=true|displayname=select radio|value=Walking,Running;\r\n#|question=|name=t_shirt_size|type=select|required=true|displayname=T Shirt Size|value=Please select^selected,--------^disabled,XS-Youth,S-Youth,M-Youth,L-Youth,S-Adult,M-Adult,L-Adult,XL-Adult,XXL-Adult,XXXL-Adult;\r\n#|type=paragraph|paragraph=t-shirt size not guarantee after Oct. 5, 2012<br/>$10 per person. <br/>$15 registration day of the event;\r\n#|question=|name=terms_and_conditions|type=textarea|required=false|displayname=|readonly=true|initialvalue=TERMS AND CONDITIONS\r\n\r\nBy indicating your acceptance, you understand and agree with the following:\r\n\r\nI know that running and walking in a road race is a potentially hazardous activity, and I attest that I am medically able and properly trained to participate in this event.\r\n\r\nI agree to abide by any decision of a race official relative to my conduct during the race.\r\n\r\nIf I should suffer injury or illness, I authorize the officials of the race to use their discretion to have me transported to a medical facility, and I take full responsibility for this action.\r\n\r\nI know that even if protection is provided, there is likely to be traffic on or near the course.\r\n\r\nI assume all risks associated with my voluntary participation in this event, including but not limited to falls, contact with other participants, the effects of any type of weather, traffic, and the conditions on the road, with all such risks being known and appreciated by me.\r\n\r\nKnowing these facts, and in consideration of my accepted entry, I for myself, my heirs, executors, administrators or anyone else who might claim on my behalf, covenant not to sue and WAIVE, RELEASE and DISCHARGE: Touching Heart, the officers, agents, volunteers, representatives, successors, and assigns of each, as well as all sponsoring organizations and their representatives, from ANY AND ALL claims or liabilities, whether foreseen or unforeseen, for death, personal injury, theft or property damage arising out of, or in the course of, my participation in this event.\r\n\r\nI further grant full permission to the event coordinators and volunteers and/or agents authorized by them, to use any photographs, videotapes, motion pictures, recordings, or other record of the event for any reasonable purpose.\r\n\r\nI understand that my entry is non-refundable.|cols=45|rows=5;\r\n#|question=|name=I_Agree|type=checkbox|required=true|displayname=I Agree to the Terms and Conditions|checked=false|value=Yes;\r\nquestion=*type=hidden*required=true*initialvalue=value;\r\n#|question=|name=Submit|type=button|displayname=submit', '<p><strong>You have registered to Kids on the Run! Good Luck!</strong></p>\r\n<form id="formbuy1" action="https://www.paypal.com/cgi-bin/webscr" accept-charset="UNKNOWN" enctype="application/x-www-form-urlencoded" method="post"><input type="hidden" name="cmd" value="_xclick"><input type="hidden" name="item_name" value="tshirt"><input type="hidden" name="business" value="helen.yi@touchingheart.com"> <input type="image" src="/en/images/paynow.gif" border="0" name="submit" alt=" Paypal Button!"><img alt=\'\' border=\'0\' src=\'https://www.paypal.com/en_US/i/scr/pixel.gif\' width=\'1\' height=\'1\'><input name="on0" type="hidden" value="Sizes" /><input type="hidden" name="os0" value="$t_shirt_size"><input name="item_number" type="hidden" value="$full_name" /><input type="hidden" name="amount" value="12.00"></form><img src="/en/images/logo_ccVisa.gif" border="0" alt="Visa" width="37" height="21" /><img src="/en/images/logo_ccMC.gif" border="0" alt="MasterCard" width="37" height="21" /><img src="/en/images/logo_ccAmex.gif" border="0" alt="Amex" width="37" height="21" /><img src="/en/images/logo_ccDiscover.gif" border="0" alt="Discover" width="37" height="21" /><img src="/en/images/logo_paypal.gif" alt="Paypal" width="33" height="21" />'),
