	(14, 'clases', 'Clases', 'index-2', '100', 'Public', '', 'Y', 'Clases de MÃºsica. Aprenda tÃ©cnicas, manejo escenario. Grabe 10 canciones en audio y video.', 'musica,clases,canto,piano,guitarra,composici,n,musical,bogota,', 'sp', '2014-01-07 21:50:44'),
