	(21, 'produccion-musical', 'ProducciÃ³n Musical', 'index-3', '100', 'Public', '', 'Y', 'Re-estructuraciÃ³n de canciones, Re-armonizaciÃ³n, AdaptaciÃ³n a diferentes gÃ©neros musicales, Arreglos, SecuenciaciÃ³n con instrumentos virtuales, GrabaciÃ³n con instrumentos reales y mÃºsicos de sesiÃ³n, Mezcla y masterizaciÃ³n.', '', 'sp', '2015-02-23 17:51:52'),
	(22, 'estudio-de-grabacion', 'Estudio de GrabaciÃ³n', 'index-3', '100', 'Public', '', 'Y', 'Alquilamos el estudio de grabaciÃ³n por horas,y en paquetes econÃ³micos, Ingeniero de grabaciÃ³n especializado y de gran experiencia en diversos gÃ©neros musicales.', '', 'sp', '2015-02-23 19:47:35'),
